.dm-ttx{overflow:hidden;position:relative}
.dm-ttx-sc{overflow-x:auto}
.dm-ttx-t{width:100%;border-collapse:collapse;font-size:13px;min-width:560px}
.dm-ttx-t th{text-align:left;font-weight:500;font-size:12px;color:var(--dm-muted);padding:10px 8px;border-bottom:1px solid var(--dm-line);white-space:nowrap}
.dm-ttx-t th.dm-ck,.dm-ttx-t td.dm-ck{width:36px;padding-left:14px}
.dm-ttx-t th.dm-r,.dm-ttx-t td.dm-r{text-align:right}
.dm-ttx-t th:last-child,.dm-ttx-t td:last-child{padding-right:14px}
.dm-ttx-s{display:inline-flex;align-items:center;gap:4px;color:inherit;font:inherit}
.dm-ttx-s:hover{color:var(--dm-fg)}
.dm-ttx-s .dm-ar{opacity:0;transition:opacity .2s,transform .3s var(--dm-ease);display:grid}
.dm-ttx-s.dm-on{color:var(--dm-fg)}.dm-ttx-s.dm-on .dm-ar{opacity:1}.dm-ttx-s.dm-on.dm-desc .dm-ar{transform:rotate(180deg)}
.dm-ttx-t td{padding:9px 8px;border-bottom:1px solid var(--dm-line);white-space:nowrap}
.dm-ttx-t tr:last-child td{border-bottom:0}
.dm-ttx-t tbody tr{transition:background .2s}
.dm-ttx-t tbody tr:hover{background:var(--dm-wash)}
.dm-ttx-t tbody tr.dm-sel{background:var(--dm-sel)}
.dm-ttx-t .dm-nm{font-weight:500}
.dm-ttx-t .dm-ag{display:flex;align-items:center;gap:7px;color:var(--dm-fg2)}
.dm-ttx-t .dm-ag .dm-av{width:20px;height:20px;font-size:9.5px}
.dm-ttx-t td.dm-num{color:var(--dm-fg2)}
.dm-ttx-cb{width:16px;height:16px;border-radius:5px;box-shadow:inset 0 0 0 1.5px var(--dm-faint);display:grid;place-items:center;color:#fff;transition:background .25s,box-shadow .25s}
.dm-ttx-cb[aria-checked="true"],.dm-ttx-cb[aria-checked="mixed"]{background:var(--dm-accent);box-shadow:none}
.dm-ttx-cb svg{width:11px;height:11px}
.dm-ttx-st{display:inline-flex;align-items:center;gap:6px;font-size:12.5px}
.dm-ttx-bar{position:absolute;left:50%;bottom:12px;display:flex;align-items:center;gap:2px;padding:4px 4px 4px 14px;border-radius:999px;background:var(--dm-ink);color:var(--dm-on-ink);box-shadow:var(--dm-shadow-pop);transform:translate(-50%,16px) scale(.96);opacity:0;filter:blur(4px);pointer-events:none;transition:transform .45s var(--dm-ease),opacity .3s,filter .3s;white-space:nowrap}
.dm-ttx-bar.dm-show{transform:translate(-50%,0);opacity:1;filter:none;pointer-events:auto}
.dm-ttx-bar .dm-pill.dm-ghost{color:inherit;opacity:.85}.dm-ttx-bar .dm-pill.dm-ghost:hover{background:color-mix(in srgb,var(--dm-on-ink) 14%,transparent);opacity:1}
.dm-ttx-n{font-size:12.5px;margin-right:8px}
.dm-ttx-t tbody{position:relative}
.dm-ttx-pad td{height:48px;border:0}
@container (max-width:560px){.dm-ttx-t{min-width:0}.dm-ttx-t th:nth-child(6),.dm-ttx-t td:nth-child(6){display:none}.dm-ttx-t th:nth-child(5),.dm-ttx-t td:nth-child(5){padding-right:14px}}

